import{_ as o,c as a,a as s,o as n}from"./app.80edbbb0.js";const d=JSON.parse('{"title":"Tutorials","description":"","frontmatter":{},"headers":[{"level":2,"title":"Beeminding RSS Feeds with Make.com","slug":"beeminding-rss-feeds-with-make-com"},{"level":2,"title":"Beeminding a Discourse forum","slug":"beeminding-a-discourse-forum"},{"level":2,"title":"How to beemind WakaTime","slug":"how-to-beemind-wakatime"},{"level":2,"title":"How to beemind focus sessions with HeyFocus","slug":"how-to-beemind-focus-sessions-with-heyfocus"},{"level":2,"title":"More tutorials and guides","slug":"more-tutorials-and-guides"}],"relativePath":"tutorials.md"}'),t={name:"tutorials.md"};function l(r,e,i,p,c,u){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-hidden="true">#</a></h1><ul><li><a href="https://forum.beeminder.com/t/how-to-post-to-a-beeminder-goal-with-a-google-form/7746" target="_blank" rel="noopener noreferrer"><strong>How to post to a Beeminder goal with a Google Form</strong></a></li><li><a href="https://forum.beeminder.com/t/how-to-create-a-beeminder-bitbar-plugin-for-mac/7762" target="_blank" rel="noopener noreferrer"><strong>How to create a Beeminder BitBar plugin for Mac</strong></a></li></ul><h2 id="beeminding-rss-feeds-with-make-com" tabindex="-1">Beeminding RSS Feeds with <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a> <a class="header-anchor" href="#beeminding-rss-feeds-with-make-com" aria-hidden="true">#</a></h2><p>Beeminder has <a href="https://www.beeminder.com/rssminder" target="_blank" rel="noopener noreferrer">an official RSS integration</a>. However, it&#39;s limited to a single RSS feed, and it doesn&#39;t allow you to customize the datapoint value or comment. If you want to beemind multiple RSS feeds, or if you want to customize the datapoint value or comment, you can use <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a> to create a custom RSS integration.</p><p>Below are instructions for creating a simple custom RSS integration with <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a>. Once you have the basic flow set up, you can customize it to meet your needs.</p><ul><li>If you haven&#39;t already, create a Beeminder goal to track RSS posts.</li><li>Once you have your goal created, log into <a href="https://www.make.com/en" target="_blank" rel="noopener noreferrer">Make.com</a></li><li>Click on &quot;Scenarios&quot; in the left sidebar</li><li>Click the plus button in the top-right of the scenarios page to create a new scenario</li><li>You should be taken to a page that says &quot;What services do you want to integrate?&quot;</li><li>Search for and click on &quot;Beeminder&quot;</li><li>Search for and click on &quot;RSS&quot;</li><li>Click the &quot;Continue&quot; button at the top right of the page</li><li>The initial module (a big question mark with a clock) should already be selected. In the menu that should already be visible select &quot;RSS.&quot;</li><li>Select &quot;Watch RSS feed items.&quot;</li><li>Paste your RSS feed into the &quot;URL&quot; field.</li><li>Click the &quot;OK&quot; button at the bottom of the dialog.</li><li>Decide where you want the integration to start processing. I&#39;ll leave it as &quot;From now on,&quot; meaning only posts from this point on will be processed. Click &quot;OK&quot; once you&#39;ve made your selection.</li><li>Click the bump on the right side of the RSS module to add a new module.</li><li>This time select &quot;Beeminder&quot; from the menu that appears.</li><li>Select &quot;Create a Datapoint.&quot;</li><li>If you haven&#39;t already connected Beeminder to your <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a> account, click the &quot;Add&quot; button next to the &quot;Connection&quot; field.</li><li>A new dialog will appear requesting your Beeminder auth token. Copy your auth token <a href="https://www.beeminder.com/api/v1/auth_token.json" target="_blank" rel="noopener noreferrer">from this url</a> into the auth token field in <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a>.</li><li>Click &quot;Continue.&quot;</li><li>If the connection was successful, additional fields should appear underneath the &quot;Connection&quot; field.</li><li>Select your desired goal in the &quot;Goal&quot; field.</li><li>In the &quot;Value&quot; field, enter the number 1. This will set the value of each new datapoint to 1 in Beeminder.</li><li>Leave &quot;Timestamp&quot; and &quot;Daystamp&quot; empty to default to the time the datapoint is created.</li><li>Decide what you&#39;d like to include in the &quot;Comment&quot; field. You can access data from previous modules in the flow by clicking in the field. For example, you could add the RSS item&#39;s Title and URL by clicking those items in the list that appears when you place your cursor in the field.</li><li>Leave the &quot;Request ID&quot; blank.</li><li>Click &quot;OK.&quot;</li><li>Click the text to the right of the left-facing arrow at the top of the page to set a title for your flow.</li><li>Click the &quot;Run once&quot; button at the bottom of the page to test the flow and save it at the same time.</li><li>Click the left-facing arrow to exit edit mode.</li><li>Click the toggle at the top-right of the window to turn the flow on.</li><li>Click &quot;Activate&quot; in the modal that appears.</li></ul><p>You&#39;re done! This flow will now check every 15 minutes for new items in the RSS feed you provided, and will post a datapoint to your Beeminder goal for each new item.</p><h2 id="beeminding-a-discourse-forum" tabindex="-1">Beeminding a Discourse forum <a class="header-anchor" href="#beeminding-a-discourse-forum" aria-hidden="true">#</a></h2><p>The <a href="https://forum.beeminder.com/" target="_blank" rel="noopener noreferrer">Beeminder forum</a> runs on <a href="https://www.discourse.org/" target="_blank" rel="noopener noreferrer">Discourse</a>, and so do many other communities (try adding <code>.rss</code> to a Discourse URL to see whether a feed is available). Discourse publishes a per-user RSS feed of your public activity, so you can beemind your own forum participation without any custom code.</p><p>Your activity feed lives at:</p><pre><code>https://forum.beeminder.com/u/USERNAME/activity.rss
</code></pre><p>Replace <code>forum.beeminder.com</code> with any Discourse site, and <code>USERNAME</code> with your username. If you&#39;d rather only count the new topics you start, use the topics feed instead:</p><pre><code>https://forum.beeminder.com/u/USERNAME/activity/topics.rss
</code></pre><p>Plug that URL into Beeminder&#39;s <a href="https://www.beeminder.com/rssminder" target="_blank" rel="noopener noreferrer">official RSS integration</a>, or into the <a href="http://Make.com" target="_blank" rel="noopener noreferrer">Make.com</a> flow above if you want to customize the datapoint value or comment.</p><h2 id="how-to-beemind-wakatime" tabindex="-1">How to beemind WakaTime <a class="header-anchor" href="#how-to-beemind-wakatime" aria-hidden="true">#</a></h2><p><a href="https://wakatime.com/" target="_blank" rel="noopener noreferrer">WakaTime</a> tracks how much time you spend programming via open-source plugins for 90+ editors and IDEs. Beeminder has an <a href="https://www.beeminder.com/wakatime" target="_blank" rel="noopener noreferrer">official WakaTime autodata integration</a>, so you don&#39;t need any scripting to beemind your coding time.</p><ul><li>Install the <a href="https://wakatime.com/integrations" target="_blank" rel="noopener noreferrer">WakaTime plugin</a> for your editor.</li><li>Go to <a href="https://www.beeminder.com/wakatime" target="_blank" rel="noopener noreferrer">beeminder.com/wakatime</a> (or click the WakaTime logo on the Beeminder front page).</li><li>Click &quot;Connect to WakaTime,&quot; then press &quot;Authorize&quot; on WakaTime to grant Beeminder access to your data.</li><li>Create a goal for time spent programming and code like normal \u2014 Beeminder will alert you if you&#39;re not putting in enough hours.</li></ul><p>For more detail, see the <a href="https://help.beeminder.com/" target="_blank" rel="noopener noreferrer">help article</a> and the <a href="https://blog.beeminder.com/wakatime/" target="_blank" rel="noopener noreferrer">announcement on the blog</a>. Note that WakaTime data can lag by about a day, so don&#39;t panic if today&#39;s coding hasn&#39;t shown up yet.</p><h2 id="how-to-beemind-focus-sessions-with-heyfocus" tabindex="-1">How to beemind focus sessions with HeyFocus <a class="header-anchor" href="#how-to-beemind-focus-sessions-with-heyfocus" aria-hidden="true">#</a></h2><p><a href="https://heyfocus.com/" target="_blank" rel="noopener noreferrer">HeyFocus</a> is a Mac app that blocks distracting sites and apps during a focus session, and it can be driven by the <code>focus://</code> URL scheme. The script below starts a focus session of a given length and, when you stop it, posts the number of hours you focused to a Beeminder goal.</p><div class="language-bash"><span class="copy"></span><pre><code><span class="line"><span style="color:#676E95;font-style:italic;">#!/bin/bash</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Usage: ./focus.sh MINUTES</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Requires HeyFocus (or another app that handles the focus:// URL scheme).</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A6ACCD;">BM_USER=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">your_username</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">BM_GOAL=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">your_goal</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">BM_TOKEN=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">your_auth_token</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;">   </span><span style="color:#676E95;font-style:italic;"># from https://www.beeminder.com/api/v1/auth_token.json</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A6ACCD;">MIN=</span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">1</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">!</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">[[</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;$</span><span style="color:#A6ACCD;">MIN</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">=~</span><span style="color:#A6ACCD;"> ^</span><span style="color:#89DDFF;">[</span><span style="color:#A6ACCD;">0-9</span><span style="color:#89DDFF;">]</span><span style="color:#A6ACCD;">+$ </span><span style="color:#89DDFF;">]];</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;font-style:italic;">then</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Usage: ./focus.sh MINUTES</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&gt;&amp;2</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#82AAFF;">exit</span><span style="color:#A6ACCD;"> 1</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">fi</span></span>
<span class="line"><span style="color:#A6ACCD;">START=</span><span style="color:#89DDFF;">$(</span><span style="color:#C3E88D;">date +%s</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># When you press Ctrl+C, end the focus session and post the elapsed hours.</span></span>
<span class="line"><span style="color:#82AAFF;">handler</span><span style="color:#89DDFF;">()</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  open </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">focus://unfocus</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">  END=</span><span style="color:#89DDFF;">$(</span><span style="color:#C3E88D;">date +%s</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#A6ACCD;">  HOURS=</span><span style="color:#89DDFF;">$(</span><span style="color:#C3E88D;">echo </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">(</span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">END</span><span style="color:#C3E88D;"> - </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">START</span><span style="color:#C3E88D;">) / 3600</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;"> </span><span style="color:#89DDFF;">|</span><span style="color:#C3E88D;"> bc -l</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Focused for </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">HOURS</span><span style="color:#C3E88D;"> hours</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">  curl -X POST \\</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">https://www.beeminder.com/api/v1/users/</span><span style="color:#89DDFF;">\${</span><span style="color:#A6ACCD;">BM_USER</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">/goals/</span><span style="color:#89DDFF;">\${</span><span style="color:#A6ACCD;">BM_GOAL</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">/datapoints.json</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> \\</span></span>
<span class="line"><span style="color:#A6ACCD;">    -d auth_token=</span><span style="color:#89DDFF;">&quot;\${</span><span style="color:#A6ACCD;">BM_TOKEN</span><span style="color:#89DDFF;">}&quot;</span><span style="color:#A6ACCD;"> \\</span></span>
<span class="line"><span style="color:#A6ACCD;">    -d value=</span><span style="color:#89DDFF;">&quot;\${</span><span style="color:#A6ACCD;">HOURS</span><span style="color:#89DDFF;">}&quot;</span><span style="color:#A6ACCD;"> \\</span></span>
<span class="line"><span style="color:#A6ACCD;">    -d comment=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">focus.sh</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#82AAFF;">exit</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#82AAFF;">trap</span><span style="color:#A6ACCD;"> handler SIGINT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Start the focus session, then wait out the timer (or stop early with Ctrl+C).</span></span>
<span class="line"><span style="color:#A6ACCD;">open </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">focus://focus?minutes=</span><span style="color:#89DDFF;">\${</span><span style="color:#A6ACCD;">MIN</span><span style="color:#89DDFF;">}&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">sleep </span><span style="color:#89DDFF;">&quot;$((</span><span style="color:#C3E88D;">MIN </span><span style="color:#89DDFF;">*</span><span style="color:#C3E88D;"> </span><span style="color:#F78C6C;">60</span><span style="color:#89DDFF;">))&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">handler</span></span>
<span class="line"></span></code></pre></div><p>Save it as <code>focus.sh</code>, run <code>chmod +x focus.sh</code>, and start a 25-minute session with <code>./focus.sh 25</code>. Stop early at any time with Ctrl+C and it still posts the time you actually focused.</p><p>For a fuller version \u2014 pink-noise audio, posting to several goals at once, and credentials kept in an <code>.env</code> file \u2014 see Narthur&#39;s <a href="https://github.com/narthur/focus.sh/blob/main/focus.sh" target="_blank" rel="noopener noreferrer">focus.sh</a> on GitHub.</p><h2 id="more-tutorials-and-guides" tabindex="-1">More tutorials and guides <a class="header-anchor" href="#more-tutorials-and-guides" aria-hidden="true">#</a></h2><p>Beyond the tutorials above, the official channels are the best place to find more how-tos:</p><ul><li><a href="https://blog.beeminder.com/" target="_blank" rel="noopener noreferrer">Beeminder Blog</a> \u2014 frequent how-tos, deep dives, and integration announcements.</li><li><a href="https://help.beeminder.com/" target="_blank" rel="noopener noreferrer">Beeminder Help</a> \u2014 the official help center, organized by topic.</li><li><a href="https://forum.beeminder.com/" target="_blank" rel="noopener noreferrer">Beeminder Forum</a> \u2014 search the community for setups and recipes, or ask your own question.</li></ul>`,26)])])}var m=o(t,[["render",l]]);export{d as __pageData,m as default};
